package com.techconsulting.lending.domain;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="loan_report_staging") @Getter @Setter
public class LoanReportStaging { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="import_batch_id") private Long importBatchId; @Column(name="source_row_number") private int rowNumber; @Column(name="raw_row_json",columnDefinition="json") private String rawRowJson; @Column(name="scheme_id") private String schemeId; @Column(name="loan_id") private String loanId; @Column(name="borrower_name") private String borrowerName; @Column(name="loan_type") private String loanType; private BigDecimal tenure; @Column(name="tenure_type") private String tenureType; @Column(name="invested_amount") private BigDecimal investedAmount; @Column(name="loan_amount") private BigDecimal loanAmount; @Column(name="amount_received") private BigDecimal amountReceived; @Column(name="investment_date") private LocalDate investmentDate; @Column(name="loan_status") private String loanStatus; private Integer dpd; private String source; @Column(name="validation_status") private String validationStatus; @Column(name="validation_errors",columnDefinition="text") private String validationErrors; @Column(name="processing_status") private String processingStatus; @Column(name="processed_at") private Instant processedAt; }
